const ROWS = [];
function row(r) { ROWS.push(r); }
const MAREN = 'Elder Maren as an elderly anthropomorphic TORTOISE standing upright (about 0.7 of the hero\'s height): a domed mossy shell with small white wildflowers growing in its seams worn like a backpack under her shawl; a long wrinkled neck; a wise beaked tortoise face with heavy-lidded amber eyes behind small round brass spectacles; a few wisps of white hair under a knitted cap; a patchwork shawl in four faded colours (blue, green, mustard, rose) with tassels; a cream robe and a brown leather belt; a satchel of pie tins; a walking stick carved with four symbols (sun, leaf, moon, drop). Warm, grumpy, kind. Not a human woman: the head, hands and feet are a tortoise\'s.';

// 1. Elder Maren redo (portrait + expressions + sprites)
row({ id: 'NPC-ELDER', cat: 'Portrait', zone: 'Crosspath', name: 'Elder Maren (tortoise redo, base portrait)', purpose: 'The first face the game relies on; the sheet, bible and dialogue all say tortoise, the current portrait is a human woman with a shell.', where: 'Every Maren dialogue (DialogueBox), the Codex', standin: 'the current human-with-shell portrait', size: '2:3 1024x1536, transparent', dest: 'Approved_Characters', file: 'NPC-ELDER.png', prio: 'High', lock: 'PORTRAIT', desc: MAREN + ' Base expression: patient, one brow raised, a small knowing half-smile, the stick in both hands.', notes: 'Replaces the existing file by the same name (the importer re-copies on a changed MD5). Expressions below.' });
row({ id: 'NPC-ELDER_HAPPY', cat: 'Portrait', zone: 'Crosspath', name: 'Elder Maren HAPPY', purpose: 'Her pie moments and the reunion lines.', where: 'Dialogue with the [happy] tag', standin: 'the current HAPPY file', size: '2:3 1024x1536, transparent', dest: 'Approved_Characters', file: 'NPC-ELDER_HAPPY.png', prio: 'High', lock: 'PORTRAIT', desc: MAREN + ' Expression: a small closed-eyed smile, head tilted, one hand offering a wedge of pie on a tin plate.', notes: 'Same framing as the base.' });
row({ id: 'NPC-ELDER_WORRIED', cat: 'Portrait', zone: 'Crosspath', name: 'Elder Maren WORRIED', purpose: 'The memories and the capture news.', where: 'Dialogue with the [worried] tag', standin: 'the current WORRIED file', size: '2:3 1024x1536, transparent', dest: 'Approved_Characters', file: 'NPC-ELDER_WORRIED.png', prio: 'High', lock: 'PORTRAIT', desc: MAREN + ' Expression: neck drawn in a little toward the shell, brows knitted, both hands tight on the stick.', notes: '' });
row({ id: 'SPR-ELDER', cat: 'NPC sprite', zone: 'Crosspath', name: 'Elder Maren world sprites (tortoise redo, stationary set)', purpose: 'She stands at her lane in Crosspath and in the forest finale; must match the new portrait.', where: 'Crosspath (her lane), the forest epilogue', standin: 'the current human-with-shell sprite set', size: 'four 2:3 1024x1536 PNGs, transparent, rel height 0.7', dest: 'Approved_Sprites', file: 'SPR-ELDER-FRONT_IDLE.png, SPR-ELDER-SIDE_IDLE.png, SPR-ELDER-BACK_IDLE.png, SPR-ELDER-FRONT_TALK.png', prio: 'High', lock: 'SPRITE', desc: MAREN + ' Full body, leaning on the stick; FRONT_TALK: one hand raised mid-sentence, the pie satchel open.', notes: 'Same file names as today: the sprite importer re-cuts them (bash tools/import_npc_sprites.sh).' });

// 2. Roaming enemies: sprite sets + Bestiary squares
for (const key in FOES) {
  const f = FOES[key];
  const files = f.set === 'walk'
    ? `SPR-FOE-${key}-{FRONT,FRONTSIDE,SIDE,BACKSIDE,BACK}_IDLE.png, SPR-FOE-${key}-{FRONT,FRONTSIDE,SIDE,BACKSIDE,BACK}_WALK.png (4-frame strips), SPR-FOE-${key}-FRONT_TALK.png`
    : `SPR-FOE-${key}-{FRONT,SIDE,BACK}_IDLE.png, SPR-FOE-${key}-FRONT_TALK.png`;
  row({ id: `SPR-FOE-${key}`, cat: 'Enemy sprite', zone: f.zone, name: `${f.name} (${f.set} set)`, purpose: 'Every roaming enemy becomes a painted 2.5D sprite like the NPCs; today a 3D stand-in in a painted world.', where: `${f.zone}: roams the lanes (ZoneEnemy); the first enemies a player meets in the open world`, standin: '3D model (KayKit / Kenney / procedural primitives)', size: `2:3 1024x1536 per pose, transparent; walk strips 3:2 1536x1024; relative height ${f.size}`, dest: 'Approved_Sprites', file: files, prio: 'High', lock: 'SPRITE', desc: `${f.name}: ${f.look}. Rim and accent colour: ${f.path}. FRONT_TALK is its threat pose (the moment it spots the hero).`, notes: `Set key FOE-${key}; the game swaps it in automatically once imported (ZoneEnemy.sprite_key). Add a row to npc_sprite_batch.csv with source id NPC-FOE-${key} and height ${f.size} so the importer scales it.` });
}
for (const key of ['PANTRY-HOUND', 'LOST-JUNIOR-CLERK', 'BIN-RACCOON', 'QUOTA-SPOTTER']) {
  const f = FOES[key];
  row({ id: `BST-${key}`, cat: 'Bestiary', zone: f.zone, name: `${f.name} (Bestiary square)`, purpose: key === 'QUOTA-SPOTTER' ? 'Renamed and reimagined from the Flexing Brute; the old picture shows a human brute.' : 'A new Bestiary entry (the town roamers were never in the Collection Book).', where: 'Battle plate (round portrait), Collection Book', standin: key === 'QUOTA-SPOTTER' ? 'the old BST-FLEXING-BRUTE picture' : 'an icon', size: '1:1 1024x1024', dest: 'Approved_Bestiary', file: `BST-${key}.png`, prio: 'High', lock: 'BESTIARY', desc: `${f.name}: ${f.look}. Background in the ${f.zone} palette.`, notes: 'The same character as its sprite set.' });
}

// 3. Cut-outs for every entrance + Bestiary squares still missing
for (const c of CAST) {
  const key = c.npc.substr(c.npc.indexOf('-') + 1);
  row({ id: `CUT-${key}`, cat: 'Cut-out', zone: c.zone, name: `${c.name} (entrance cut-out)`, purpose: 'The boss / lieutenant / gatekeeper entrance now slides a cut-out character in over the letterbox beside the name card.', where: 'BossIntro, before the battle', standin: `the dialogue portrait ${c.npc} (transparent, used tonight)`, size: '2:3 1024x1536, transparent, hips up', dest: 'Approved_Characters', file: `CUT-${key}.png`, prio: c.prio, lock: 'CUTOUT', desc: `Exactly the character of dialogue portrait ${c.npc} (same face, outfit, colours), hips up: ${c.pose}. Rim light: ${c.path}.`, notes: 'Optional: the dialogue portrait already works in the intro; a cut-out only adds the wider framing and pose.' });
  if (c.bst) {
    const bstId = 'BST-' + c.name.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');
    row({ id: bstId, cat: 'Bestiary', zone: c.zone, name: `${c.name} (Bestiary square)`, purpose: 'The 21 Bestiary squares still missing are all speaking bosses; the square shows on the battle plate and in the Collection Book.', where: 'Battle plate, Collection Book', standin: `a square crop of portrait ${c.npc}`, size: '1:1 1024x1024', dest: 'Approved_Bestiary', file: `${bstId}.png`, prio: 'Medium', lock: 'BESTIARY', desc: `Exactly the character of dialogue portrait ${c.npc}, head and shoulders, ${c.pose}; dark background in the ${c.zone} palette.`, notes: c.name === 'Captain Spotless' ? 'Also serves BST-ENFORCER-CAPTAIN-SPOTLESS (the Old Service Tunnels name): save a copy under that id too.' : '' });
  }
}
row({ id: 'CUT-PRIMM_CRACKED', cat: 'Cut-out', zone: 'Castle', name: 'Primm, phase 2 (Reflection) cut-out', purpose: 'The three-phase final fight; phase 2 is the mirror.', where: 'BossIntro of "Primm - Reflection" (today the same picture for all phases)', standin: 'CUT-PRIMM / NPC-PRIMM', size: '2:3 1024x1536, transparent', dest: 'Approved_Characters', file: 'CUT-PRIMM_CRACKED.png', prio: 'Low', lock: 'CUTOUT', desc: 'Exactly the character of NPC-PRIMM, hips up, but his reflection in the mirror behind him is the Wanderer (scruffy brown hair, mustard tunic, dark teal cloak) and a hairline crack runs down the mirror; his smile is held a little too long.', notes: 'Needs a small code hook (phase -> expression suffix) before it shows; listed so the set is complete.' });
row({ id: 'CUT-PRIMM_UNRAVELLED', cat: 'Cut-out', zone: 'Castle', name: 'Primm, phase 3 (Unraveling) cut-out', purpose: 'The last phase: the rules break and the sincerity cracks.', where: 'BossIntro of "Primm - Unraveling"', standin: 'CUT-PRIMM / NPC-PRIMM', size: '2:3 1024x1536, transparent', dest: 'Approved_Characters', file: 'CUT-PRIMM_UNRAVELLED.png', prio: 'Low', lock: 'CUTOUT', desc: 'Exactly the character of NPC-PRIMM, hips up, circlet askew, coat creased for the first time, the mirror behind him shattered into purple-lit shards, his expression hurt rather than angry ("I only wanted it to be nice").', notes: 'As above.' });

// 4. Remaining 3D-model NPCs
row({ id: 'SPR-PRIMM', cat: 'NPC sprite', zone: 'Capital', name: 'Primm, at work (postgame world sprite, stationary set)', purpose: 'The one list NPC still drawn as a tinted KayKit knight: Primm under guard on the wells and pipes in the Crease after his fall.', where: 'The Capital (the Crease), postgame', standin: 'KayKit Knight, tinted', size: 'four 2:3 1024x1536 PNGs, transparent, rel height 1.0', dest: 'Approved_Sprites', file: 'SPR-PRIMM-FRONT_IDLE.png, SPR-PRIMM-SIDE_IDLE.png, SPR-PRIMM-BACK_IDLE.png, SPR-PRIMM-FRONT_TALK.png', prio: 'Medium', lock: 'SPRITE', desc: 'Exactly the character of dialogue portrait NPC-PRIMM but in his postgame state: no circlet, the grey coat with the sleeves rolled, a wrench in one hand and a drain plan under the other arm, a guard\'s iron cuff on one wrist; dignified, tired, sincere. FRONT_TALK: explaining a pipe with two fingers.', notes: 'Set key PRIMM; NpcSprites picks it up automatically.' });
row({ id: 'SPR-DUMPWORKER', cat: 'NPC sprite', zone: 'Verdant Dump', name: 'Dump farmhand (three nameless workers, stationary set)', purpose: 'The three bark NPCs on the terraces are the last 3D models in the Dump.', where: 'Verdant Dump terraces (bark.worker_1..3)', standin: 'KayKit Barbarian / Rogue / Mage with hats', size: 'four 2:3 1024x1536 PNGs, transparent, rel height 1.0', dest: 'Approved_Sprites', file: 'SPR-DUMPWORKER-FRONT_IDLE.png, SPR-DUMPWORKER-SIDE_IDLE.png, SPR-DUMPWORKER-BACK_IDLE.png, SPR-DUMPWORKER-FRONT_TALK.png', prio: 'Medium', lock: 'SPRITE', desc: 'A stocky humanoid mole farmhand in patched overalls, a straw hat with a wildflower in the band, muddy boots, a pitchfork with a tin can stuck on one prong, a satchel of seed packets; cheerful and muddy. FRONT_TALK: leaning on the fork, one hand up. Three in-game copies will be tinted slightly differently.', notes: 'Needs a one-line data hook (sprite key on the worker entries) once imported.' });
row({ id: 'DUMP-PROP-PRIMM-STATUE', cat: 'Zone prop', zone: 'Capital', name: 'Golden Primm statue (cut-out prop)', purpose: 'The Capital\'s statue is a gold-tinted knight model.', where: 'Capital, the Primm statue fountain and the Showcase Quarter', standin: 'KayKit Knight, gold tint', size: '2:3 1024x1536, transparent', dest: 'Approved_ZoneKits/Capital', file: 'CAPI-PROP-PRIMM-STATUE.png', prio: 'Low', lock: 'CUTOUT_PROP', desc: 'A gleaming gold statue of Primm (exactly NPC-PRIMM\'s face and coat, idealised: taller, chin higher, one hand raised in benediction) on a white marble plinth with a gold laurel, viewed from the front-left at the storybook camera angle, polished highlights.', notes: 'A second, toppled version (STATUE-FALLEN) is nice for the ending but optional.' });

// 5. Story stills
const STILLS = [
  ['STORY-CAPTURE', 'Capital', 'Elowen taken at the castle gate (pc_capture)', 'High', 'The main path\'s cruellest beat has no picture: Plume names her and the guards take her.', 'The first castle run, node 1 (StoryScenePlayer pc_capture)', 'Before the white-and-gold castle gate at cold morning, two Correction Officers in mirrored visors seize Elowen (exactly NPC-ELOWEN: hooded traveller, dark hair, medic satchel) by the arms; she is looking back over her shoulder at the viewer, not afraid, mouthing a word; Percival Plume (NPC-PLUME, the peacock minister) stands to the side with a scroll, smiling; the Wanderer\'s shadow falls into the frame from the bottom left. Key light cold from the upper right; the gate behind is too perfect.'],
  ['STORY-THRONE', 'Castle', 'The Pathwork Throne (ending beat 8)', 'High', 'Everything returns at once: the lullaby, the name, all four Paths. The game\'s emotional climax is a code-drawn glyph today.', 'Ending beat "throne"', 'Deep under the castle, a stair of four woven colours (red, blue, purple, green) winds down to a throne grown from four seats into one; the Wanderer (CHAR-REF: scruffy brown hair, mustard tunic, dark teal cloak, seen from behind and slightly above) has just sat, both hands on the arms, and four-coloured light pours up and out through the roots in the walls; the only warm light in the frame. No faces: the moment belongs to the player.'],
  ['STORY-WONDER', 'Endless Buffet', 'The true Chef\'s dish (cutscene wonder)', 'High', 'The Buffet\'s freeing: dinner proves who she is and she gives the Doppelganger her name. The reveal has a still; the resolution does not.', 'Cutscene "wonder" after the Test Kitchen boss', 'The Grand Chef (exactly NPC-ESCOFFINA, frost still in her hair from ten years in the freezer) sets a plain, golden, enormous dish on the Grand Kitchen\'s pass; steam rises; a crowd of chefs and golems lean in; the faceless shifting figure in a chef\'s coat (the Doppelganger\'s true form from STORY-DOPPEL) holds a spoon in both hands, hesitating; Basil (NPC-BASIL, the rabbit line cook) in the front with his eyes wide. Warm copper and candle light, the first honest meal.'],
  ['STORY-VACANCY', 'D.N.A.', 'Agnes takes the office (cutscene vacancy)', 'Medium', 'The D.N.A.\'s freeing has STORY-APPROVAL after the boss; the moment Agnes decides to stay deserves its own frame.', 'Cutscene "vacancy"', 'The Office of Final Approval in cold 4:59 light: Agnes Overdue (exactly NPC-AGNES, the ghost with the enormous stack) standing behind the great desk for the first time, one hand flat on a new blank handbook, the other handing a numbered ticket to a bewildered Mortimer Grimsby (NPC-MORTIMER, the skeleton CE-No) who holds it like a small dead thing; Gerald (NPC-GERALD) in the doorway with his number finally lit green; the queue machines dark behind them.'],
  ['STORY-SEVER', 'Verdant Dump', 'Letting the seed die (cutscene sever)', 'Medium', 'The Dump\'s freeing beat: the first honest compost in ten years. STORY-ROTHEART covers the boss, not the goodbye.', 'Cutscene "sever"', 'The Heart Roots at golden hour: Archdruid Compostella (exactly NPC-COMPOSTELLA, grandmotherly, roots receding from her arms) kneeling with both hands on a small black seed in a hollow of earth, the Wanderer kneeling opposite with his hand over hers; the great grey tree behind them beginning to soften and brown at the edges; raccoons watching from the branches; the sickly green draining from the roots into warm compost brown.'],
  ['STORY-MODEL-ROOM', 'Castle', 'Primm at the model (cutscene primm_intro)', 'Medium', 'The first time the player sees Primm in person: a man moving a cottage one centimetre with tweezers.', 'Cutscene "primm_intro" before the final fight', 'A white, mirrored, perfectly symmetrical room; a table-sized model of the whole kingdom (the four zones in miniature, Crosspath, the Capital) under crisp morning light; Primm (exactly NPC-PRIMM, pressed grey coat, thin gold circlet) bent over it with a pair of tweezers, adjusting a tiny cottage, not yet looking up; every mirror reflects only him; a hairline crack in the floor at the frame\'s edge with faint purple light.'],
  ['STORY-KEPT-FACE', 'Castle', '"I kept your face" (cutscene primm_reveal)', 'Medium', 'The darker reveal for a player who rushes the castle: the painted-over royal portrait.', 'Cutscene "primm_reveal" (fewer than four zones freed)', 'Primm\'s Private Gallery: the royal family portrait in a gilded frame, the king and queen painted over in flat white brushstrokes all in one direction, only the boy\'s face (eleven, brown hair, four faint colours at his hand) left untouched; Primm (NPC-PRIMM) beside it with one gloved hand almost touching the boy\'s painted cheek; the Wanderer\'s reflection in the frame\'s glass over the boy\'s face. Cold light, one warm spot on the child.'],
  ['STORY-FACADE-FALLS', 'Capital', 'The facade falls (ending beat 3)', 'Medium', 'The Showcase Quarter\'s painted doors fall flat; a child paints the new gate sign.', 'Ending beat "facade"', 'The Showcase Quarter at real, warm afternoon light for the first time: a row of identical pastel house fronts falling forward like stage flats to show the grey honest houses behind; hedges relaxing into natural shapes; citizens (NPC-CITIZEN, no longer identical: one has taken off the wig) blinking; in the foreground a small child on a crate painting a wooden gate sign (a shape, no letters) in four colours while Wren (NPC-WREN, the wren-folk archivist) holds the paint pot.'],
  ['STORY-CELL-4', 'Lab', 'Cell 4 (the Prince\'s old cell, with Elowen)', 'Medium', 'The postgame\'s one sincere picture: ten years of tally marks and a child\'s four-colour drawing.', 'The Lab, node 11 (lab_cell scene)', 'A small white-tiled cell cracked by roots, flat fluorescent light with one warm shaft from the open door; the far wall covered floor to ceiling in tally marks scratched into the tile, and low down, at a child\'s height, a crayon drawing of four stick figures in four colours holding hands; Elowen (NPC-ELOWEN) sitting on the cot with her knees up, looking at the door where the Wanderer stands as a dark silhouette; a tin mug and a very old soup bowl on the floor.'],
  ['STORY-FUNERAL', 'Capital', 'The royal funeral (postgame)', 'Medium', 'Two hand-carved headstones at dusk; Hob walks the king and queen home.', 'Story scene royal_funeral at the end of Grave Row', 'Grave Row at dusk, headstones no longer identical: two new hand-carved stones under a lantern, flowers from the Reek heaped on them; Old Hob (NPC-HOB, the ghoul gravedigger) leaning on his spade with his hat off; Agnes (NPC-AGNES) tearing a yellowed form in two; Elder Maren (the tortoise, as in NPC-ELDER) with her hand on the Wanderer\'s back; and in the warm wind, barely there, two translucent figures in old-court dress (NPC-KING, NPC-QUEEN) turning to go. Played straight: no joke in the frame.'],
  ['STORY-HOME', 'Crosspath', 'Isla comes home', 'Medium', 'Brannoch\'s open gate finally earns its payoff.', 'Story scene isla_homecoming', 'Crosspath\'s north gate at golden hour: Gatekeeper Brannoch (NPC-GATEKEEPER, the enormous bear) halfway through dropping his notebook, Isla (NPC-ISLA, a young bear with her mother\'s curls, a facade-crew paint smock, a travel bag) coming down the Capital road with a tired small wave; townsfolk pretending not to watch; the fountain\'s four plinths behind. Warm, no punchline.'],
  ['STORY-MEMORY-3', 'Global', 'Memory 3: the coup', 'High', 'The key reveal of the middle game: the man in white and gold kneels, then stands.', 'Memory screen fragment 3 (today text over a four-colour vignette)', 'A throne room at night, banners of four colours woven as one behind the Pathwork Throne; a man in white and gold (Primm, ten years younger, no circlet) rising from one knee before King Harmon (NPC-KING) and Queen Concordia (NPC-QUEEN); the king and queen pushing a boy of eleven behind them toward the dark; guards\' shadows in the doorway where a figure in a white coat (Siphon) has stepped aside. Dreamlike edges, the four colours bleeding into the dark, one cold light on the kneeling man.'],
  ['STORY-MEMORY-4', 'Global', 'Memory 4: a name', 'High', 'The reveal: "Tessar!"', 'Memory screen fragment 4', 'A sunlit castle courtyard with the Wayweaver crest (four Path symbols in a ring) carved over a door; a boy of eleven with scruffy brown hair turning at a shout, a dumbbell dropped at his feet, four colours flickering in his open hand; the blurred warm shapes of a father and mother at the colonnade; a young Elder Maren (the tortoise, younger: fewer wrinkles, a dark shawl) watching from a bench with a book. Soft, warm, slightly over-exposed like a memory.'],
  ['STORY-MEMORY-1', 'Global', 'Memory 1: warmth', 'Medium', 'The lullaby and a hand on his head.', 'Memory screen fragment 1', 'A nursery at night seen from a child\'s height, four-coloured light from a lamp, a woman\'s silhouette (Queen Concordia, face unseen, humming) with a hand resting on a boy\'s head in the foreground; lavender on the sill, woodsmoke haze; everything soft-edged and golden except the four colours.'],
  ['STORY-MEMORY-2', 'Global', 'Memory 2: the cells', 'Medium', '"I wasn\'t lost. I was kept."', 'Memory screen fragment 2', 'A white, sterile corridor of glass tanks glowing faintly in the four Path colours, seen from inside a cell through bone-pale bars; white coats and clipboards passing without faces; a mug on a desk; a tally mark being scratched by a small hand in the foreground. Cold, flat, ordinary; the horror is the ordinariness.'],
];
for (const [id, zone, name, prio, purpose, where, desc] of STILLS) {
  row({ id, cat: 'Story still', zone, name, purpose, where, standin: 'code-drawn stage glyphs / a text vignette / a portrait', size: '16:9 1792x1024 (keep the upper part)', dest: 'Approved_KeyArt', file: `${id}.png`, prio, lock: 'STILL', desc, notes: 'Needs a one-line hook in cutscene_defs / ending_defs / memory_screen once the file exists (the key-art importer already accepts STORY-* ids).' });
}

// 6. Cards without art
for (const [id, name, path, desc] of CARDS) {
  row({ id, cat: 'Card', zone: 'Global', name: `${name} (card art)`, purpose: 'The Oct 27 review\'s new cards and the Oct 28 Hazmat Intern have placeholders; their sheet rows carry only the style lock.', where: 'Hand, field, Deck Station, packs, shops', standin: 'the placeholder (a game-icons silhouette on a Path gradient)', size: '2:3 1024x1536', dest: 'Approved', file: `${id}.png`, prio: path === 'Necrocrat' && (id === 'N-35' || id === 'N-38') ? 'High' : (id === 'B-35' || id === 'G-34' || id === 'R-34' ? 'High' : 'Medium'), lock: 'CARD', desc, notes: id === 'N-38' ? 'New tonight (Part 1); paste the description into the sheet\'s Image description too.' : 'Paste the description into the sheet\'s Image description column (col I) as well.' });
}
row({ id: 'N-10-REDO', cat: 'Card', zone: 'Global', name: 'Push Broom of Undeath (art no longer matches)', purpose: 'The card is a +0/+1 Tool that destroys two resources when the attached unit attacks; the art shows a shredder vortex from the old Shred text.', where: 'As above', standin: 'the current N-10 art', size: '2:3 1024x1536', dest: 'Approved', file: 'N-10.png', prio: 'Low', lock: 'CARD', desc: 'Cool grays with sickly green highlights. A skeletal janitor in a tie riding on the back of a charging zombie unit, sweeping a wide push broom ahead of them that scatters iron plates, scraps and ingredients off the edge of the frame into dustbins; green office light.', notes: 'Optional redo; replace by the same file name.' });

// 7. Icons
for (const [id, name, who, desc] of [
  ['ICON-GEAR-QUOTASSTOPWATCH', 'Quota\'s Stopwatch', 'Vivienne Quota', 'Beefcake accent. A brass stopwatch with a red second hand frozen at the top, a tiny crossed-out barbell engraved on the lid, a short chain.'],
  ['ICON-GEAR-COLONELSLADLE', 'The Colonel\'s Ladle', 'Colonel Crumb', 'Gourmand accent. A heavy copper ladle with a military rank chevron stamped on the bowl, a parsley sprig tied to the handle, one drip of grey paste.'],
  ['ICON-GEAR-PLUMESQUILL', 'Plume\'s Notary Quill', 'Percival Plume', 'Necrocrat accent. A long iridescent peacock-feather quill with a gold notary seal dangling from it, the nib dripping sickly green ink.'],
  ['ICON-GEAR-CLIPWELLSSHEARS', 'Clipwell\'s Golden Shears', 'Hortensia Clipwell', 'Refusemancer accent. Ornate gold garden shears with ivy-carved handles, closed, one snipped leaf falling from the blades.'],
]) {
  row({ id, cat: 'Icon', zone: 'Capital', name: `${name} (gear icon)`, purpose: `The lieutenant relic from ${who} shows the closest existing gear icon.`, where: 'Character screen, Bertram\'s armory lists, the reward box', standin: 'the placeholder gear icon', size: '1:1 1024x1024, transparent', dest: 'Approved_Icons', file: `${id}.png`, prio: 'Medium', lock: 'ICON', desc, notes: '' });
}
for (const [group, desc] of [
  ['STORY', 'a quill writing on a parchment scroll with a four-coloured ribbon'], ['ZONES', 'a signpost with four arms in the four Path colours'],
  ['SIDE', 'a small door ajar in a hillside with a warm light inside'], ['CHALLENGES', 'a laurel wreath round a single raised fist'],
  ['COLLECTION', 'a fanned hand of three cards with a foil shine'], ['PATHS', 'the four Path symbols (barbell, ladle, stamp, leaf) in a ring'],
  ['MIXED', 'two interlocked rings, one red and one green'], ['SECRET', 'a key with a question-mark bow'],
]) {
  row({ id: `ICON-FEAT-${group}`, cat: 'Icon', zone: 'Global', name: `Feat group icon: ${group.toLowerCase()}`, purpose: 'Part 3\'s Feats screen shows one icon per feat group; existing icons stand in.', where: 'Menu > Feats, the unlock toast', standin: 'an existing icon of the group\'s theme', size: '1:1 1024x1024, transparent', dest: 'Approved_Icons', file: `ICON-FEAT-${group}.png`, prio: 'Low', lock: 'ICON', desc: `Parchment gold and warm brown with a small badge shape behind it: ${desc}.`, notes: 'Generate all eight in one conversation so the set matches.' });
}
row({ id: 'COS-HAT-LEAFCROWN-SHEET', cat: 'Cosmetic', zone: 'Verdant Dump', name: 'Leaf Crown hat (redo sheet)', purpose: 'The user asked for a redo of the crown of living leaves (the secret cosmetic hinted by Pip Threadwell).', where: 'The hero\'s head (tailor, wardrobe, the world)', standin: 'the current LEAFCROWN sheet', size: 'one row of five hats FRONT, FRONTSIDE, SIDE, BACKSIDE, BACK, 2560x1024, transparent', dest: 'Approved_Cosmetics', file: 'COS-HAT-LEAFCROWN-SHEET.png', prio: 'Medium', lock: 'HAT', desc: 'A crown woven from living oak and ivy leaves in three greens with a few gold autumn leaves, tiny white wildflowers at the temples, thin green vines binding it, one small acorn at the front; dewy, slightly glowing at the leaf edges; sits low on the brow.', notes: 'Same file name as the current sheet; the cosmetics importer re-splits and re-fits it.' });

// 8. Zone landmarks, backdrops, props and decals (from docs/art/art_direction_oct28.md)
